/**
 * Compact FOSS catalog wave: ~22 curated mods per existing FOSS title.
 * Prefer github-zip when releases ship archives; hubs as external.
 */
import { ghMod, type ModSeed } from "./modSeedHelpers";

type Def = {
  slug: string;
  title: string;
  tagline: string;
  desc: string;
  base: string;
  baseTitle: string;
  path: string;
  website: string;
  repo?: string;
  kind?: "github-zip" | "direct-zip" | "external";
  pattern?: string;
  size?: number;
  year?: number;
  changes: string;
  summary: string;
  art?: { from: string; to: string; icon: string };
  hint?: string;
  license?: string;
};

function m(d: Def): ModSeed {
  const kind = d.kind ?? (d.repo ? "github-zip" : "external");
  return ghMod({
    slug: d.slug,
    title: d.title,
    tagline: d.tagline,
    description: d.desc,
    baseGameSlug: d.base,
    baseTitle: d.baseTitle,
    developerSlug: "indie-web",
    license: d.license ?? "Open Source / Community",
    releaseYear: d.year ?? 2024,
    sizeMB: d.size ?? 100,
    website: d.website,
    githubRepo: d.repo ?? null,
    downloadKind: kind,
    assetPattern: kind === "github-zip" ? d.pattern ?? "\\.zip$" : null,
    installRelativePath: d.path,
    art: d.art ?? { from: "#1e293b", to: "#64748b", icon: "Package" },
    summary: d.summary,
    changes: d.changes,
    installHint: d.hint,
  });
}

